const takeLimit = `-- name: TakeLimit :one
INSERT INTO access_limits(bucket,attempts,expires_at) VALUES ($1,1,$2)
ON CONFLICT(bucket) DO UPDATE SET
attempts=CASE WHEN access_limits.expires_at<=$3 THEN 1 ELSE LEAST(access_limits.attempts+1,10001) END,
expires_at=CASE WHEN access_limits.expires_at<=$3 THEN EXCLUDED.expires_at ELSE access_limits.expires_at END
RETURNING attempts
`

type TakeLimitParams struct {
	Bucket      []byte
	ExpiresAt   pgtype.Timestamptz
	ExpiresAt_2 pgtype.Timestamptz
}

func (q *Queries) TakeLimit(ctx context.Context, arg TakeLimitParams) (int32, error) {
	row := q.db.QueryRow(ctx, takeLimit, arg.Bucket, arg.ExpiresAt, arg.ExpiresAt_2)
	var attempts int32
	err := row.Scan(&attempts)
	return attempts, err
}

